local KTool = CS.Engine.Lib.KTool
local IDType            = typeof(CS.Game.Native.Common.ID)
local UIModule = CS.Engine.UI.UIModule
local KCookie = CS.Engine.Lib.KCookie

--- from: Assets/BundleResources/Prefabs/Common/CommonPrivilegeCardNode.prefab > name: CommonPrivilegeCardNode
---@class CommonPrivilegeCardNode
---@field Env                           	CommonPrivilegeCardNode                 
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Text                          	UnityEngine.RectTransform               
---@field ImgIcon                       	UnityEngine.RectTransform               
---@field BtnPrivilegeCard              	UnityEngine.RectTransform               
local CommonPrivilegeCardNode = Class('CommonPrivilegeCardNode')
function CommonPrivilegeCardNode:__init()

end

function CommonPrivilegeCardNode:__delete()

end

function CommonPrivilegeCardNode:Awake()
    local IdComp = self.controller.gameObject:EnsureComponent(IDType)
    if IdComp then
        self.key = IdComp.stringId
    end
    SetButtonAction(self.BtnPrivilegeCard,Bind(self,self.OnBtnPrivilegeCardClick))
end

function CommonPrivilegeCardNode:Start()
    if not isNull(self.key) then
        local isHavePrivilege = GameUtils.IsHavePrivilegeCard(1)
        self:RefreshShow(isHavePrivilege)
        KTool.SetActive(self.controller.gameObject,true)
    else
        KTool.SetActive(self.controller.gameObject,false)
    end
end

function CommonPrivilegeCardNode:RefreshShow(isHave)
    local state = isHave and 1 or 2
    CfUtils.SetUISwitchImage(self.ImgIcon,state)

    local str = isHave and self:GetDescByKey() or localize("调查官特权未激活")
    CfUtils.FillText(self.Text,str)

end

function CommonPrivilegeCardNode:GetDescByKey()
    if isNull(self.key) or string.isEmpty(self.key) then
        return ""
    end
    local key = table.concat({self.key,"Desc"})
    return GameUtils.GetPrivilegeCardDescByName(1,key)
end

function CommonPrivilegeCardNode:OnBtnPrivilegeCardClick()
    if BattleViewMgr then
        return
    end
    local WelfareConstants = import("Game.UI.Welfare.WelfareConstants")

     local lastDialog = UIModule.CurrentScreen:LastDialog()
     if lastDialog.Argument.id == Constants.UITypeIds.UIWelfareMainDialog then
         local index = lastDialog.Env:GetIndexByWelfareId(WelfareConstants.OpenIds.SubScribe)
         lastDialog.Env:RefreshSelfByIndex(index)
     else
         UIModule.OpenDialog({
             id = Constants.UITypeIds.UIWelfareMainDialog,
             parameters = {
                 selectedIndex = WelfareConstants.OpenIds.SubScribe
             }
         }, GameUtils.GetAllExcludeIds() )
     end
end

function CommonPrivilegeCardNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

